from stats import max_by_key

def test_max_by_key_dict():
    rows = [{"v": 1}, {"v": 9}, {"v": 5}]
    assert max_by_key(rows, lambda r: r["v"]) == {"v": 9}

def test_max_by_key_empty():
    assert max_by_key([], len) is None

def test_max_by_key_tie():
    assert max_by_key(["bb", "aa"], len) == "bb"


